    'runner_beat_at', (select h.at from public.ops_heartbeats h where h.name = 'runner'),
    'oldest_due_age_s', (
      select floor(extract(epoch from p_now - min(j.run_after)))::bigint
      from public.jobs j
      where j.status in ('queued', 'failed') and j.run_after <= p_now
    )
  );
$$;

